const limites = {
  brecha: 72,
  acceso: 30,
};
const avisos = {
  brecha: 24,
  acceso: 5,
};
function estado(tipo, pasado) {
  const lim = limites[tipo];
  if (lim === undefined) {
    return "desconocido";
  }
  if (typeof pasado !== "number") {
    return "dato erróneo";
  }
  const r = lim - pasado;
  if (r < 0) {
    return "vencido";
  }
  if (r <= avisos[tipo]) {
    return "urgente";
  }
  return "en plazo";
}
console.log(estado("brecha", 60));
console.log(estado("queja", 5));
console.log(estado("brecha", "x"));

